// 5. Un-ticking demotes the existing credential rather than waiting for the next one.
auth.setRemember(false);
check('forget: token back in sessionStorage', sessionStorage.getItem('claudinite-dashboard:token') === TOK);
check('forget: durable copy erased', localStorage.getItem('claudinite-dashboard:token') === null);
restart();
check('forget: gone after a browser restart', auth.currentToken() === '');

// 6. Sign-out leaves no copy in either store, whichever one held it.
auth.setRemember(true);
auth.setPastedToken(TOK);
auth.signOut();
check('signOut: localStorage clear', localStorage.getItem('claudinite-dashboard:token') === null);
check('signOut: sessionStorage clear', sessionStorage.getItem('claudinite-dashboard:token') === null);
check('signOut: currentToken empty', auth.currentToken() === '');

// 7. The OAuth landing stores through the same choice.
auth.setRemember(true);
globalThis.location = { search: '', href: 'https://x.test/', origin: 'https://x.test', pathname: '/' };
globalThis.history = { replaceState() {} };
sessionStorage.setItem('claudinite-dashboard:oauth-state', 'st8');
globalThis.fetch = async () => ({ ok: true, status: 200, json: async () => ({ access_token: TOK }) });
const back = await auth.completeSignIn({ clientId: 'c', exchangeUrl: 'https://e.test' }, { search: '?code=abc&state=st8', replaceUrl: false });
check('oauth: signed in', back.status === 'signed-in');
check('oauth: honoured remember me', localStorage.getItem('claudinite-dashboard:token') === TOK);

console.log(failed ? `\n${failed} FAILED` : '\nall passed');
process.exit(failed ? 1 : 0);
