  /* --- controls --- */
  /* `topbar`, not `bar`: `.bar` is the outcome mini-chart below, and a header
     sharing that name inherits its 7px×108px geometry. */
  header.topbar {
    position: sticky; top: 0; z-index: 5;
    background: var(--surface);
    border-bottom: 1px solid var(--rule);
  }
  .topbar-in { max-width: 1180px; margin: 0 auto; padding: 12px 20px;
               display: flex; gap: 12px; align-items: center; flex-wrap: wrap; }
  .grow { flex: 1 1 auto; }
  input, button, select {
    font: inherit; color: var(--ink); background: var(--surface);
    border: 1px solid var(--border); border-radius: 7px; padding: 6px 9px;
  }
  input { min-width: 190px; }
  select { max-width: 260px; }
  button { cursor: pointer; }
  button:hover { border-color: var(--muted); }
  button[disabled] { opacity: .5; cursor: default; }
  button.primary { background: var(--s-blue); border-color: var(--s-blue); color: #fff; font-weight: 600; }
  .hint { color: var(--muted); font-size: 12px; }
  .authbox { display: inline-flex; align-items: center; gap: 8px; }
  .avatar { border-radius: 50%; display: block; }

  /* --- stat tiles: the headline numbers, no chart needed --- */
  .tiles { display: grid; grid-template-columns: repeat(auto-fit, minmax(148px, 1fr));
           gap: 10px; margin-bottom: 22px; }
  .tile { background: var(--surface); border: 1px solid var(--border);
          border-radius: 10px; padding: 12px 14px; }
         padding: 10px 14px; border-radius: 0 8px 8px 0; margin-bottom: 14px; }
  /* The explainer rides in the topbar and opens OVER the page. It answers a question
     you have once — "what is this thing doing with my credential" — and as a block in
     the flow it pushed the content it explains down the screen on every load after
     that one. `position: fixed` rather than absolute: the topbar is sticky, and an
     absolutely-positioned panel inside it is clipped by the bar's own height. */
  details.setup { position: relative; }
  details.setup > summary { cursor: pointer; list-style: none; font-size: 12px;
                  border: 1px solid var(--border); border-radius: 999px;
                  padding: 2px 9px; color: var(--ink-2); background: var(--surface); }
  details.setup > summary::-webkit-details-marker { display: none; }
  details.setup > summary:hover { border-color: var(--ink-2); color: var(--ink); }
  details.setup[open] > summary { border-color: var(--ink-2); color: var(--ink); }
  .setup-body { position: fixed; top: 52px; right: 20px; z-index: 20; width: min(480px, calc(100vw - 40px));
                max-height: calc(100vh - 72px); overflow: auto;
                background: var(--surface); border: 1px solid var(--border);
                border-radius: 10px; padding: 4px 16px 12px;
                box-shadow: 0 12px 32px color-mix(in srgb, var(--ink) 18%, transparent); }
  .setup-body p, .setup-body li { color: var(--ink-2); }
  .setup-body p:last-child { margin-bottom: 4px; }

  /* The member cell. Stars used to ride here beside CI; it is `git-github`'s
     contribution now and lands in the subrow with everything else a pack reports. */
  .member { display: flex; gap: 9px; align-items: baseline; }


  /* --- pack-contributed metrics ---------------------------------------------------
     Two surfaces for one contract: a card per pack on the repo page, and one line per
     pack in a member's subrow on the fleet page. */

  .pack-cards { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
                gap: 10px; }
  .pack-card { background: var(--surface); border: 1px solid var(--border);
               border-radius: 10px; padding: 12px 14px 14px;
               display: flex; flex-direction: column; gap: 10px; }
  .pack-head { display: flex; align-items: center; gap: 8px; }
